WITH bounds AS (
  SELECT max(orderdate)::date AS end_date
  FROM sales.salesorderheader
),
w AS (
  SELECT end_date,
         end_date - 89 AS cur_start,
         end_date - 90 AS prev_end,
         end_date - 179 AS prev_start
  FROM bounds
)
SELECT
  w.end_date::text AS anchor_date,
  w.cur_start::text AS start_date,
  (SELECT count(*) FROM sales.salesorderheader AS header WHERE header.orderdate::date BETWEEN w.cur_start AND w.end_date AND header.onlineorderflag)::text AS expected_value,
  (SELECT count(*) FROM sales.salesorderheader AS header WHERE header.orderdate::date BETWEEN w.prev_start AND w.prev_end AND header.onlineorderflag)::text AS baseline_value,
  NULL::text AS expected_dimension
FROM w;
